INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by) VALUES ('TensorLBM', 'm18114 XVAL-LBM-FREE-ENERGY-BINARY-EQUILIBRIUM-PRESSURE', 18207, 2, '{"impl_files": ["docs/board_audit/m18207/evidence/impl__binary_equilibrium_pressure.py"], "entry": "docs/board_audit/m18207/evidence/entry__run_xval.py", "run_artifacts": ["docs/board_audit/m18207/evidence/artifact_json__xval_binary_equilibrium_pressure.json", "docs/board_audit/m18207/evidence/artifact_png__fig_convergence_and_lbm.png"], "tests": ["tests/test_binary_equilibrium_pressure_xval.py 复跑 7 passed rc=0（本单实跑 8.82s）；快照 docs/board_audit/m18207/evidence/tests__test_binary_equilibrium_pressure_xval.py"], "integration_callers": "none（本单实测 grep：run_binary_equilibrium_pressure_benchmark 仅定义于 src/tensorlbm/multiphase_benchmarks.py:713，run_multiphase_benchmark_suite 未注册、benchmarks/bench_multiphase.py 未导入、平台侧无引用；phasefield/__init__.py 只是包级导出→ 无下游调用方，L3 不达）", "benchmark": {"registered_cases_psql": [{"case_name": "FE-FLAT-BAND-SURFACE-TENSION (periodic two-interface band, Nx=64 Ny=8, xi=3, A=0.1, kappa=0.45; 4000 steps)", "id": 85, "metric": "sigma = (1/2) sum_x (P_xx - P_yy) from the second moment of the populations (half for two interfaces); P_NN uniformity max_x|P_NN-mean|/mean as the mechanical-equilibrium check", "status": "passed", "tolerance": "<15% owner band; measured sigma rel err 2.0097e-02, Pnn uniformity 1.4799e-05 (auditor bitwise re-run)"}, {"case_name": "FE-STATIC-DROPLET-LAPLACE (R=16, xi=2, 96x96, 8000 steps; R=24, xi=2, 128x128, 10000 steps)", "id": 86, "metric": "dp = p_in - p_out from p=(P_xx+P_yy)/2 of the populations; REPORTED ERROR IS A SINGLE SNAPSHOT: the dp series is not converged (both arms hit the predeclared step budget, stopping rule drift<1e-3 never met), snapshot scatter 5.75% (R16) / 7.82% (R24), time-mean of the 2nd half -1.35% (R16) / -9.78% (R24)", "status": "passed", "tolerance": "<15% owner band; snapshot 0.18% (R16) and 13.48% (R24), time-mean 1.35% / 9.78% => inside the band, the 0.18% precision claim is ~30x smaller than the run''s own scatter"}, {"case_name": "FE-DECLARED-CURVATURE-ARM-STABILITY (dropR36: R=36, xi=3, kappa=0.45, L=176, 12000 steps)", "id": 87, "metric": "all fields finite through the declared step budget", "status": "failed", "tolerance": "measured: p_in/p_out/dp/u_max/rho_min/rho_max are NaN from the first logged step (step 500) in the delivered dropR36.json, and the auditor''s 600-step probe reproduces NaN; the arm is absent from results.json and the report calls it ''submitted but not completed'' => stability gate FAILED"}], "delivered_ref_vs_got": [{"interface_cells": 1.5, "sigma_ref": 1.0, "sigma_got": 0.8984864380581464, "sigma_rel_err": -0.10151356194185357, "p_nn_uniformity_rel": 0.23090448902262384, "coex_rel_err": 0.0, "lbm_p_nn_total_dev_rel": 0.1498940400673252, "lbm_umax": 0.012920161353952141}, {"interface_cells": 2.0, "sigma_ref": 1.3333333333333333, "sigma_got": 1.252140297068228, "sigma_rel_err": -0.060894777198828964, "p_nn_uniformity_rel": 0.14189782776962157, "coex_rel_err": 4.050093593832571e-13, "lbm_p_nn_total_dev_rel": 0.08298665375751524, "lbm_umax": 0.00816019944628625}, {"interface_cells": 3.0, "sigma_ref": 2.0, "sigma_got": 1.9431423769586074, "sigma_rel_err": -0.028428811520696318, "p_nn_uniformity_rel": 0.06697300072185863, "coex_rel_err": 1.7386053485779485e-08, "lbm_p_nn_total_dev_rel": 0.03666952600497808, "lbm_umax": 0.002968533863016212}], "owner_band": 0.15, "max_abs_sigma_rel_err": 0.10151356194185357, "within_owner_band": true, "replica_of_case85": {"kappa": 0.45, "lbm_max_velocity": 0.0002997289190344166, "lbm_rho_range": [0.9989926621559655, 1.0024602914330298], "lbm_total_p_nn_deviation_relative": 0.03592527160640512, "note": "登记 case 85 的 ref sigma=(2/3)A xi 仅在 A=B 时等于 (2 sqrt2/3)sqrt(kappa A^3)/B；本复算 A=B=0.1, kappa=0.45 -> sigma_analytic=0.2 与登记 ref 一致", "p_nn_max_deviation_relative_static": 0.06429810130152479, "registered_case_85_got": "sigma rel err 2.0097e-02, Pnn uniformity 1.4799e-05 （m17964 从 population 二阶矩测；本单复算口径不同，见 A6 注）", "replica_config": {"A": 0.1, "B": 0.1, "interface_cells": 3.0, "kappa": 0.45, "nx": 64, "ny": 8, "steps": 4000, "tau_f": 1.0}, "scheme_iso9_vs_5pt_grad_x_max_delta": 5.551115123125783e-17, "scheme_iso9_vs_5pt_sigma_delta": 0.0, "sigma_analytic": 0.2, "sigma_measured_static_tensor": 0.19431422306586354, "sigma_relative_error": -0.028428884670682275, "xi_from_model": 3.0}}, "repro_cmd": "cd /root/tp-agent/work/m18114 && python xval/XVAL-LBM-FREE-ENERGY-BINARY-EQUILIBRIUM-PRESSURE/run_xval.py --out /tmp/repro18114", "external_anchor": "Pooley, Furtado & Carr, PRE 78, 056709 (2008)（90 度接触角 free-energy LBM 的解析平衡锚）；σ=(2√2/3)√(κA³)/B 与 p_coex=A²/(4B) 为本单独立重推；登记基准行 tensor_benchmark_cases id=85/86/87", "repro_verified": {"rc": 0, "wall_s": 46.26, "checks_bitwise_equal": true, "rows_bitwise_equal": true, "rerun_sha256": "bb130d7504caebc674f2cb4808a47eed82ff8c5682cb0938136cb6e6323cd459", "verdict_line": ["VERDICT: PASS  (artifacts: /tmp/m18207_repro_wkm7ikry)", "CH phase-flux gap diagnostic: {\"diffusion_length_estimate\": 10.327955589886443, \"numerical_diffusivity_cs2_tau_minus_half\": 0.06666666666666665, \"peak_decay_ratio\": -0.04901487789510806, \"peak_final\": -0.0490148778940977, \"peak_initial\": 0.9999999999793865, \"steps\": 400.0, \"tau_g\": 0.7}"]}, "provenance": {"subject_worktree": "/root/tp-agent/work/m18114", "subject_head": "c6ed86d2", "snapshots": {"artifact_json": {"origin": "/root/tp-agent/work/m18114/xval/XVAL-LBM-FREE-ENERGY-BINARY-EQUILIBRIUM-PRESSURE/artifacts/xval_binary_equilibrium_pressure.json", "sha256": "bb130d7504caebc674f2cb4808a47eed82ff8c5682cb0938136cb6e6323cd459", "bytes": 13868}, "artifact_png": {"origin": "/root/tp-agent/work/m18114/xval/XVAL-LBM-FREE-ENERGY-BINARY-EQUILIBRIUM-PRESSURE/artifacts/fig_convergence_and_lbm.png", "sha256": "f8d143deae9d58fec4ef8fec7fa75087f6e451d2c33fe0bcc186f80fbef156f8", "bytes": 105928}, "doc": {"origin": "/root/tp-agent/work/m18114/docs/XVAL_LBM_FREE_ENERGY_BINARY_EQUILIBRIUM_PRESSURE.md", "sha256": "f7e9b35492499761bde71475dccad46f8b9c3d1ef2435b97e388cc8997ea1ea2", "bytes": 9789}, "entry": {"origin": "/root/tp-agent/work/m18114/xval/XVAL-LBM-FREE-ENERGY-BINARY-EQUILIBRIUM-PRESSURE/run_xval.py", "sha256": "4ae95da9a918abfade7e5e4ebfcd5344369507683a3ef645bd96649bf4f70d75", "bytes": 8208}, "impl": {"origin": "/root/tp-agent/work/m18114/src/tensorlbm/phasefield/binary_equilibrium_pressure.py", "sha256": "9cc550088c4d544f811b730828c00a984dcfac9e8373dea5b6d840c33e1afa0a", "bytes": 21262}, "impl_pkg_init": {"origin": "/root/tp-agent/work/m18114/src/tensorlbm/phasefield/__init__.py", "sha256": "f467ff4dedb2150b68571f8810aa309529bda30a23c5be031c5dea0ba238f162", "bytes": 3856}, "impl_wrapper": {"origin": "/root/tp-agent/work/m18114/src/tensorlbm/multiphase_benchmarks.py", "sha256": "86526e69f7d3e5843d918a508eeeb9a6a596d3a828e3eb16c2ab2085e2c92e1b", "bytes": 76613}, "predeclared": {"origin": "/root/tp-agent/work/m18114/xval/XVAL-LBM-FREE-ENERGY-BINARY-EQUILIBRIUM-PRESSURE/predeclared.json", "sha256": "cdc69af146390e9bee871fdd51cab638c9ae5acb089a70b4b160d6abad42c471", "bytes": 3098}, "tests": {"origin": "/root/tp-agent/work/m18114/tests/test_binary_equilibrium_pressure_xval.py", "sha256": "65e24871730b340d1086026d40683e5dc7020a455c01a24967a2a98ed3faade6", "bytes": 5564}}, "in_ecosystem_main": {"eco_head": "0c7a9b15", "eco_repo": "/root/tensor-ecosystem/TensorLBM", "git_cat_file_impl": "ABSENT\nfatal: path ''src/tensorlbm/phasefield/binary_equilibrium_pressure.py'' does not exist in ''HEAD''", "note": "交付物只在被审工作树 /root/tp-agent/work/m18114 head=c6ed86d2 上；生态 main 无该模块，亦无 agent/m18114 远端分支 → 下游仓/平台当前无法消费", "remote_branch_agent_m18114": "0"}}, "findings": [{"id": "F1", "severity": "blocking-for-L3", "claim": "无下游调用方", "evidence": "无真正的下游调用方：run_multiphase_benchmark_suite 未注册该 benchmark，benchmarks/bench_multiphase.py 未导入，平台侧无 API 引用；phasefield/__init__.py 属包级导出（公共 API），不等于调用方", "impact": "L3/L4 不达；交付不可被套件/平台消费"}, {"id": "F2", "severity": "blocking-for-L4", "claim": "基准覆盖不全", "evidence": "登记行 86（droplet Laplace R16/R24）与 87（dropR36 稳定性，status=failed）在交付模块中无对应能力（模块无 droplet/Laplace 臂）；行 87 为锚点级 honest-FAIL 未消", "impact": "锚点基准只被部分覆盖；已覆盖的平面族 σ 10.15/6.09/2.84% 全在 <15% 带内"}, {"id": "F3", "severity": "material", "claim": "双梯度格式（iso9/5pt）在平界面配置下恒等", "evidence": "grad_x 最大差 5.551e-17，σ 差 0.0e+00；y 不变场使 Tomita 权重 (4/12+1/12+1/12)=1/2 退化为中心差分", "impact": "文档所称『离散敏感性可测而非假设』在 1-D 变化场上未被真正行使，scheme 行是重复计数"}, {"id": "F4", "severity": "material", "claim": "σ 口径与登记行不同", "evidence": "交付 σ 取自解析平衡场的自由能压力张量（0.194314），登记行 85 的 got 取 population 二阶矩；本单用交付模块复算 case85 配置得 -2.8429%（登记 got 2.0097e-02），同带内但不可逐位复现；Pnn 均匀性交付 3.59e-02（LBM 总压）vs 登记 1.4799e-05（population 口径）", "impact": "基准行与交付工件不是同一测量口径，裁判可比性需补注；不构成造假，但报告应写明"}, {"id": "F5", "severity": "minor", "claim": "交付物未进生态 main", "evidence": "ABSENT\nfatal: path ''src/tensorlbm/phasefield/binary_equilibrium_pressure.py'' does not exist in ''HEAD''", "impact": "当前只在 agent/m18114 本地分支，合并前下游不可用"}, {"id": "F6", "severity": "minor", "claim": "文档/自述瑕疵", "evidence": "run_xval.py 文档串声明两张 png，实际只 savefig 一张；m18114 result.checks 把 PNG 的 105928 B 写成 JSON 大小（JSON 实为 13868 B）", "impact": "不影响判据数字，属自述准确性瑕疵"}], "why_not_L3": "L3 需主求解器/平台侧真调用方；本单 grep 实测无调用点（F1）。phasefield/__init__.py 的导出是公共 API 暴露，不是调用者；方向相反的『验证模块调用生产 free_energy_step/stream』是好事但不算 integration_callers。", "why_not_L4": "L4 需 L3 全过；另基准覆盖只到平面族（F2），登记行 86/87 未覆盖，行 87 仍 failed；且 σ 口径与登记行不同（F4），ref vs got 不可逐位复现。", "not_checked": ["登记行 86 的 droplet Laplace 两臂未复算（交付模块无该能力）", "登记行 87 的 dropR36 稳定性未复算（交付模块无该能力，且登记为 failed）", "未审查 GPU/CUDA 路径（交付为 CPU torch float64）", "未做网格无关性以外的参数扫描（tau_f、Gamma 未扫描）"]}', 'board-audit')
